sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 position;
uniform float depth;
uniform float scale;
uniform float starSize;
uniform float feather;
layout(color) uniform half4 color;
uniform float alpha;
uniform float amount;
uniform float brightness;
uniform float blend;
float hash12(float2 p) {
    float3 q = fract(float3(p.xyx) * 0.1031);
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float zoom = max(scale, 0.01);
    float cell = 16.0 * zoom;
    float density = clamp(amount / 100.0 * 0.7, 0.0, 1.0);
    float glow = 0.0;
    for (int k = 0; k < 6; k++) {
        float layer = mod(float(k) - depth * 0.01, 6.0);
        float d = 0.4 + layer * 0.6;
        float fade = smoothstep(0.0, 0.6, layer) * smoothstep(6.0, 5.0, layer);
        float id = floor(float(k) - depth * 0.01 - layer + 0.5) + float(k) * 13.0;
        float2 p = (coord - size * 0.5 - position / d) * d / cell + id * 7.13;
        float2 n = floor(p);
        if (hash12(n + id * 3.7) > density) continue;
        float2 at = float2(hash12(n + 1.3 + id), hash12(n + 5.9 - id)) * 0.8 + 0.1;
        float r = starSize * 0.5 * zoom / d;
        float amp = min(r * r * 4.0, 1.0);
        float re = max(r, 0.5);
        float soft = 0.5 + feather * 0.15 * zoom / d;
        float dist = length((p - n - at) * cell / d);
        glow += fade * amp * (1.0 - smoothstep(max(re - soft, 0.0), re + soft, dist));
    }
    float s = clamp(glow * brightness, 0.0, 1.0) * clamp(alpha, 0.0, 1.0) * float(color.a);
    float3 base = float3(src.rgb) / float(src.a);
    float3 c = float3(color.rgb);
    float3 rgb = blend < 0.5 ? mix(base, c, s) : blend < 1.5 ? base + c * s : blend < 2.5 ? 1.0 - (1.0 - base) * (1.0 - c * s) : mix(base, base * c, s);
    return half4(half3(clamp(rgb, 0.0, 1.0)) * src.a, src.a);
}
